mapper.select:
select std.DOCUMENT_ID, std.EHARS_UID, std.UNIQ_NO, std.EHARS_STATENO, std.NYEHMS_STATENO, std.FNAME, std.LNAME, std.MNAME, std.SSN, std.DOB, std.DOB_TEXT, std.GENDER, std.RACE_ASIAN, std.RACE_BLACK, std.RACE_INDIAN, std.RACE_MULTIPLE, std.RACE_OTHER, std.RACE_PACIFIC, std.RACE_UNKNOWN, std.RACE_WHITE, std.RACE, std.RES_STATE, std.DEATH_CERT, std.DEATH_STATE, std.REPORT_STATE_CD, std.UNDERLYING, std.NDI_BIR_DAY, std.NDI_BIR_MO, std.NDI_BIR_YEAR, std.NDI_FIRST, std.NDI_LAST, std.NDI_MIDDLE, std.NDI_RACE, std.NDI_SEX, std.NDI_SSN, std.NDI_ST_RES, std.NDI_DOD, std.NDIFILE_CAT, std.EHARS_DOD, std.EHARS_YEAR_DEATH, std.NDI_MONTH_DEATH, std.NDI_DAY_DEATH, std.NDI_YEAR_DEATH, std.DOD_TEXT, std.NDI_FILE, std.EHARS_IMPORT_DATE, std.CITYNO, std.CAUSE1, std.NATURE_INJURY_FLAG1, std.CAUSE2, std.NATURE_INJURY_FLAG2, std.CAUSE3, std.NATURE_INJURY_FLAG3, std.CAUSE4, std.NATURE_INJURY_FLAG4, std.CAUSE5, std.NATURE_INJURY_FLAG5, std.CAUSE6, std.NATURE_INJURY_FLAG6, std.CAUSE7, std.NATURE_INJURY_FLAG7, std.CAUSE8, std.NATURE_INJURY_FLAG8, std.CAUSE9, std.NATURE_INJURY_FLAG9, std.CAUSE10, std.NATURE_INJURY_FLAG10, std.CAUSE11, std.NATURE_INJURY_FLAG11, std.CAUSE12, std.NATURE_INJURY_FLAG12, std.CAUSE13, std.NATURE_INJURY_FLAG13, std.CAUSE14, std.NATURE_INJURY_FLAG14, std.CAUSE15, std.NATURE_INJURY_FLAG15, std.CAUSE16, std.NATURE_INJURY_FLAG16, std.CAUSE17, std.NATURE_INJURY_FLAG17, std.CAUSE18, std.NATURE_INJURY_FLAG18, std.CAUSE19, std.NATURE_INJURY_FLAG19, std.CAUSE20, std.NATURE_INJURY_FLAG20, pda.STATENO, pda.DISCARD_STATUS
